(()=>{
const KEY='bol2_saves_v1';
const slots=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch{return[]}};
const write=x=>localStorage.setItem(KEY,JSON.stringify(x));
const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));
const blank=()=>({studioName:'',year:1,week:1,money:100000000,energy:100,reputation:35,films:[],awards:[],news:[],talentContracts:{},relationships:{},transactions:[],industry:{trend:'Drama',marketHealth:82,boxOfficeIndex:100,streamingDemand:78},updatedAt:null,studio:{}});
const filmStages=[['development','Development & Writing'],['preproduction','Pre-Production'],['production','Filming'],['postproduction','Post-Production'],['marketing','Marketing'],['ready','Ready for Release'],['released','Released']];
const crewRoles=[['director','Director'],['writer','Writer'],['cinematographer','Cinematographer'],['composer','Composer'],['vfx','VFX Supervisor'],['editor','Editor']];
const talent=Object.values(window.INDUSTRY_PEOPLE||{}).flat().map(t=>{const role=String(t.role||'').toLowerCase();let category='Actor';if(role.includes('director'))category='Director';else if(role.includes('writer'))category='Writer';else if(role.includes('composer'))category='Composer';else if(role.includes('cinematographer'))category='Cinematographer';else if(role.includes('vfx'))category='VFX Supervisor';else if(role.includes('editor'))category='Editor';return [t.name,category,t.talent,Number(t.fee)/1000000]});
const filmName=stage=>filmStages.find(x=>x[0]===stage)?.[1]||'Development & Writing';
function toast(t){let n=document.querySelector('.notice');if(!n){n=document.createElement('div');n.className='notice';document.body.appendChild(n)}n.textContent=t;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),1800)}
function saveCurrent(s,silent=false){s.updatedAt=new Date().toISOString();const ss=slots();let i=ss.findIndex(x=>x?.studioName===s.studioName);if(i<0)i=ss.findIndex(x=>!x);if(i<0)i=0;ss[i]=s;write(ss);if(!silent)toast('Studio saved.');}
function render(){document.querySelector('#app').innerHTML=`<main class="screen"><section class="menu"><h1 class="brand">BOX OFFICE LEGENDS</h1><div class="tag">Build the studio. Make the movies. Change the industry.</div><div class="menuButtons"><button class="menuBtn primary" id="new">🎬 CREATE A STUDIO<span class="sub">Found your own studio career</span></button><button class="menuBtn" id="continue">▶ CONTINUE<span class="sub">Resume your latest saved studio</span></button><button class="menuBtn" id="load">💾 LOAD STUDIO<span class="sub">Open one of your save slots</span></button><button class="menuBtn" id="settings">⚙ SETTINGS<span class="sub">Game preferences</span></button><button class="menuBtn" id="about">ℹ ABOUT<span class="sub">About Box Office Legends 2.0</span></button></div><div class="industry"><div><small>Top Studio</small><b>—</b></div><div><small>Biggest Film</small><b>—</b></div><div><small>Trending Genre</small><b>Drama</b></div></div><div class="version">FOUNDATION BUILD · v2.0.0</div></section></main><div class="notice"></div>`;
document.querySelector('#new').onclick=newGame;document.querySelector('#continue').onclick=()=>{const s=slots().filter(Boolean).sort((a,b)=>new Date(b.updatedAt||0)-new Date(a.updatedAt||0))[0];s?start(s):toast('No saved studio yet.')};document.querySelector('#load').onclick=loadModal;document.querySelector('#settings').onclick=window.openSettings;document.querySelector('#about').onclick=aboutModal;}
function aboutModal(){const e=document.createElement('div');e.className='modal';e.innerHTML=`<div class="panel"><div class="panelHead"><button class="close">×</button><h2>The Story of Box Office Legends</h2><p>The original simulator and its return.</p></div><div style="padding:22px;color:#c9c4b8;font-size:11px;line-height:1.8"><h3 style="color:#d5ad58">Before Simulator 2, there was an original.</h3><p>Box Office Legends Simulator began with one idea: let players experience the movie industry from the inside — building studios, making films, hiring talent and competing with other companies.</p><p>Then the updates became quiet, the media presence faded, and people began wondering what happened to the creator.</p><p><strong style="color:#eee">Did I disappear from the media? Was Box Office Legends over?</strong></p><p>No. The time away became an opportunity to rethink the entire project. Simulator 2 is a fresh foundation built around the lessons and ambition of the original.</p><p style="text-align:center;margin-top:28px;font-family:Georgia,serif;font-style:italic;color:#e1d4b4">The story continues.</p><p style="text-align:center;margin-top:24px;color:#d5ad58;font-weight:800;letter-spacing:1px">A Game by JoshuaX Studio</p></div></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();}
window.openSettings=()=>{const K='bol2_settings_v1',d={difficulty:'Standard',autosave:true,animations:true,music:60,sfx:70};let s;try{s={...d,...JSON.parse(localStorage.getItem(K)||'{}')} }catch{s={...d}}const e=document.createElement('div');e.className='modal';e.innerHTML=`<div class="panel settingsPanel"><div class="settingsHero"><button class="close">×</button><div class="settingsIcon">⚙</div><div><div class="eyebrow">BOX OFFICE LEGENDS · SIMULATOR 2</div><h2>Settings</h2><p>Customize your studio experience.</p></div></div><div class="settingsBody"><section class="setGroup"><div class="setTitle">🎮 GAMEPLAY</div><label class="setRow"><span>Difficulty<small>Controls simulation pressure.</small></span><select id="difficulty"><option>Casual</option><option>Standard</option><option>Industry</option></select></label><label class="setRow"><span>Autosave<small>Save your studio after major actions.</small></span><button class="toggle" id="autosave"></button></label></section><section class="setGroup"><div class="setTitle">🔊 AUDIO</div><label class="setRow"><span>Music</span><input id="music" type="range" min="0" max="100"></label><label class="setRow"><span>Sound Effects</span><input id="sfx" type="range" min="0" max="100"></label></section></div></div>`;document.body.appendChild(e);e.querySelector('#difficulty').value=s.difficulty;e.querySelector('#music').value=s.music;e.querySelector('#sfx').value=s.sfx;e.querySelector('#autosave').classList.toggle('on',s.autosave);e.querySelector('#difficulty').onchange=x=>{s.difficulty=x.value;localStorage.setItem(K,JSON.stringify(s))};e.querySelector('#music').oninput=x=>{s.music=+x.value;localStorage.setItem(K,JSON.stringify(s))};e.querySelector('#sfx').oninput=x=>{s.sfx=+x.value;localStorage.setItem(K,JSON.stringify(s))};e.querySelector('#autosave').onclick=()=>{s.autosave=!s.autosave;e.querySelector('#autosave').classList.toggle('on',s.autosave);localStorage.setItem(K,JSON.stringify(s))};e.querySelector('.close').onclick=()=>e.remove()};
function newGame(){const e=document.createElement('div');e.className='modal';let name='',suffix='Studios',icon='★',primary='#d5ad58',secondary='#17120a';const suffixes=['Studios','Pictures','Entertainment','Films','Productions','Media','Motion Pictures','Animation','Television','Works','International'];const icons=['★','✦','◆','◈','●','▲','✺','✧','♛','◉'];const words=['Silverline','Northstar','Horizon','Monarch','Lumina','Summit','Redwood','Eclipse','Golden','Bluebird','Evergreen','Starlight'];const draw=()=>{e.innerHTML=`<div class="panel studioCreate"><div class="panelHead"><button class="close">×</button><div class="eyebrow">FOUNDATION · NEW CAREER</div><h2>Found Your Studio</h2><p>Build your identity before entering the industry.</p></div><div class="studioSteps"><span class="active">01 Identity</span><span>02 Profile</span><span>03 Founding</span></div><div class="studioCreateBody"><section class="studioPreview"><div class="logoPreview" style="--gold:${primary};--ink:${secondary}"><div class="logoIcon">${icon}</div><div class="logoName">${esc(name||'Your Studio')}</div><div class="logoSuffix">${esc(suffix)}</div></div><div class="previewCaption">LIVE LOGO PREVIEW</div></section><section class="studioForm"><label>Studio Name<div class="nameInput"><input id="studioName" maxlength="28" placeholder="Enter a name" value="${esc(name)}"><button id="randomName">🎲</button></div></label><label>Suffix<select id="suffix">${suffixes.map(x=>`<option ${x===suffix?'selected':''}>${x}</option>`).join('')}</select></label><label>Primary Color<input id="primary" type="color" value="${primary}"></label><label>Secondary Color<input id="secondary" type="color" value="${secondary}"></label><label>Icon<div class="iconGrid">${icons.map(x=>`<button class="iconChoice ${x===icon?'chosen':''}" data-icon="${x}">${x}</button>`).join('')}</div></label></section></div><div class="studioCreateFooter"><div><small>PREVIEW</small><b>${esc(name||'Your Studio')} ${esc(suffix)}</b></div><button class="menuBtn primary" id="continueStudio">CONTINUE →</button></div></div>`;e.querySelector('.close').onclick=()=>e.remove();const refresh=()=>{name=e.querySelector('#studioName').value.trim();suffix=e.querySelector('#suffix').value;primary=e.querySelector('#primary').value;secondary=e.querySelector('#secondary').value;const p=e.querySelector('.logoPreview');p.style.setProperty('--gold',primary);p.style.setProperty('--ink',secondary);p.querySelector('.logoIcon').textContent=icon;p.querySelector('.logoName').textContent=name||'Your Studio';p.querySelector('.logoSuffix').textContent=suffix;e.querySelector('.studioCreateFooter b').textContent=`${name||'Your Studio'} ${suffix}`};e.querySelectorAll('input,select').forEach(x=>x.oninput=refresh);e.querySelector('#randomName').onclick=()=>{name=words[Math.floor(Math.random()*words.length)];e.querySelector('#studioName').value=name;refresh()};e.querySelectorAll('[data-icon]').forEach(b=>b.onclick=()=>{icon=b.dataset.icon;e.querySelectorAll('[data-icon]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');refresh()});e.querySelector('#continueStudio').onclick=()=>{if(!name)return toast('Choose a studio name first.');e.remove();founderProfile({name,suffix,icon,primary,secondary})}};draw();document.body.appendChild(e)}
function founderProfile(d){const e=document.createElement('div');e.className='modal';let capital='Emerging',specialty='Blockbuster Entertainment',philosophy='Creative First';e.innerHTML=`<div class="panel studioCreate"><div class="panelHead"><button class="close">×</button><div class="eyebrow">FOUNDATION · STUDIO PROFILE</div><h2>Define Your Studio</h2><p>These choices shape your starting position.</p></div><div class="studioCreateBody single"><section class="profileChoices"><div class="choiceBlock"><h4>STARTING POSITION</h4><div class="choiceCards">${[['Indie','$25M',20],['Emerging','$100M',35],['Established','$500M',55],['Major','$1B',70]].map(x=>`<button class="choiceCard ${x[0]===capital?'chosen':''}" data-cap="${x[0]}"><b>${x[0]}</b><strong>${x[1]}</strong><small>Reputation ${x[2]}</small></button>`).join('')}</div></div><div class="choiceBlock"><h4>STUDIO SPECIALTY</h4><div class="choiceCards compact">${['Blockbuster Entertainment','Prestige Cinema','Commercial Entertainment','Genre Films','Animation','Independent Cinema','Television & Streaming','Global Cinema'].map(x=>`<button class="choiceCard ${x===specialty?'chosen':''}" data-spec="${x}"><b>${x}</b></button>`).join('')}</div></div><div class="choiceBlock"><h4>PHILOSOPHY</h4><div class="choiceCards compact">${['Make Money','Creative First','Star Power','Global Cinema','Prestige'].map(x=>`<button class="choiceCard ${x===philosophy?'chosen':''}" data-phil="${x}"><b>${x}</b></button>`).join('')}</div></div></section></div><div class="studioCreateFooter"><div><small>FOUNDING PROFILE</small><b>${esc(d.name)} ${esc(d.suffix)}</b></div><button class="menuBtn primary" id="foundStudio">FOUND STUDIO →</button></div></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();e.querySelectorAll('[data-cap]').forEach(b=>b.onclick=()=>{capital=b.dataset.cap;e.querySelectorAll('[data-cap]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen')});e.querySelectorAll('[data-spec]').forEach(b=>b.onclick=()=>{specialty=b.dataset.spec;e.querySelectorAll('[data-spec]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen')});e.querySelectorAll('[data-phil]').forEach(b=>b.onclick=()=>{philosophy=b.dataset.phil;e.querySelectorAll('[data-phil]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen')});e.querySelector('#foundStudio').onclick=()=>{const money={Indie:25000000,Emerging:100000000,Established:500000000,Major:1000000000}[capital];const rep={Indie:20,Emerging:35,Established:55,Major:70}[capital];const s=blank();Object.assign(s,{studioName:`${d.name} ${d.suffix}`,money,reputation:rep,studio:{logo:d,capital,specialty,philosophy}});saveCurrent(s,true);e.remove();start(s);toast(`${s.studioName} officially enters the industry.`)}}
function createMovie(state){const e=document.createElement('div');e.className='modal movieModal';let title='',genre='Drama',budget=30000000;const genres=['Drama','Comedy','Action','Horror','Romance','Thriller','Sci-Fi','Fantasy','Animation','Adventure','Crime'];const budgets=[['Small','$10M',1e7],['Moderate','$30M',3e7],['Large','$60M',6e7],['Major','$100M',1e8],['Tentpole','$200M',2e8]];e.innerHTML=`<div class="panel moviePanel"><div class="movieHero"><button class="close">×</button><div class="eyebrow">STUDIO · NEW PRODUCTION</div><h2>Make a Movie</h2><p>Create the concept first. Hiring happens through the Talent section.</p></div><div class="movieSteps"><span class="active">01 Concept</span><span>02 Crew</span><span>03 Timeline</span><span>04 Confirm</span></div><div class="movieBody"><section class="moviePreview"><div class="clapper">🎬</div><small>NEW FEATURE FILM</small><h3 id="moviePreviewTitle">Untitled Film</h3><p id="moviePreviewMeta">Drama · $30,000,000 budget</p><div class="potential"><span>Early potential</span><b>Not yet rated</b></div></section><section class="movieForm"><label>Film Title<div class="movieName"><input id="movieTitle" maxlength="40" placeholder="Write a title"><button id="randomTitle">🎲</button></div></label><label>Genre<select id="movieGenre">${genres.map(g=>`<option>${g}</option>`).join('')}</select></label><div class="formLabel">Production Budget</div><div class="budgetCards">${budgets.map(x=>`<button class="budgetCard ${x[2]===budget?'chosen':''}" data-budget="${x[2]}"><b>${x[0]}</b><strong>${x[1]}</strong></button>`).join('')}</div><div class="movieNote">Your budget influences scale, schedule, risk and commercial expectations.</div></section></div><div class="movieFooter"><div><small>NEXT</small><b>Development & Writing</b><span>Several weeks</span></div><button class="menuBtn primary" id="startMovie">CREATE CONCEPT →</button></div></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();const refresh=()=>{title=e.querySelector('#movieTitle').value.trim();genre=e.querySelector('#movieGenre').value;e.querySelector('#moviePreviewTitle').textContent=title||'Untitled Film';e.querySelector('#moviePreviewMeta').textContent=`${genre} · $${Number(budget).toLocaleString()} budget`};e.querySelector('#movieTitle').oninput=refresh;e.querySelector('#movieGenre').onchange=refresh;e.querySelector('#randomTitle').onclick=()=>{const a=['The Words We Never Said','After Midnight','A House Without Windows','Last Summer','The Long Goodbye','Echoes of Tomorrow','Paper Kingdom','The Final Frame','Under Electric Skies','Before the Lights'];e.querySelector('#movieTitle').value=a[Math.floor(Math.random()*a.length)];refresh()};e.querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>{budget=+b.dataset.budget;e.querySelectorAll('[data-budget]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');refresh()});e.querySelector('#startMovie').onclick=()=>{if(!title)return toast('Give your movie a title first.');const film={id:Date.now(),title,genre,budget,stage:'development',stageWeek:1,totalWeeks:4,quality:50,audience:50,story:50,direction:50,acting:50,visuals:50,music:50,vfx:50,crew:{},createdWeek:state.week,createdYear:state.year,spent:0,marketingBudget:0,revenue:0,boxOffice:0,streamingRevenue:0,releasedWeek:null,releaseDate:null,history:[{week:state.week,year:state.year,event:'Concept created',detail:`${genre} feature film entered development.`}]};state.films=[...(state.films||[]),film];state.energy=Math.max(0,state.energy-5);saveCurrent(state,true);e.remove();start(state);toast(`${title} entered development.`)}}
function start(s){document.querySelector('#app').innerHTML=`<main class="studioDash"><header class="dashHeader"><div class="dashBrand"><div class="dashLogo">${s.studio?.logo?.icon||'★'}</div><div><h1>${esc(s.studioName)}</h1><p>Year ${s.year} · Week ${s.week}</p></div></div><div class="dashHeaderActions"><button id="save" class="dashIcon">💾</button><button id="back" class="dashIcon">⌂</button></div></header><section class="dashStats"><div class="dashStat"><small>💰 CASH</small><b>$${Number(s.money).toLocaleString()}</b><span>Available funds</span></div><div class="dashStat energy"><small>⚡ ENERGY</small><b>${s.energy}/100</b><div class="energyBar"><i style="width:${s.energy}%"></i></div></div><div class="dashStat"><small>⭐ REPUTATION</small><b>${s.reputation}/100</b><span>Industry standing</span></div></section><div class="dashGrid"><section class="dashCard projects"><div class="cardHead"><div><small>STUDIO AT A GLANCE</small><h2>Current Projects</h2></div><button class="textBtn" id="viewMovies">VIEW ALL</button></div><div class="emptyProject"><div class="emptyIcon">🎬</div><div><b>No active projects</b><p>Your next movie could start your studio's story.</p></div><button class="projectBtn">MAKE A MOVIE</button></div></section><section class="dashCard snapshot"><div class="cardHead"><div><small>YOUR STUDIO</small><h2>At a Glance</h2></div></div><div class="metricGrid"><div><b>${s.films?.length||0}</b><span>Films</span></div><div><b>${s.awards?.length||0}</b><span>Awards</span></div><div><b>$0</b><span>Revenue</span></div><div><b>0</b><span>Employees</span></div><div><b>0</b><span>Markets</span></div><div><b>${s.year}</b><span>Year</span></div></div></section><section class="dashCard news"><div class="cardHead"><div><small>THE INDUSTRY</small><h2>Latest News</h2></div><button class="textBtn" id="viewNews">SEE ALL</button></div><article class="newsItem"><span>INDUSTRY</span><b>The film industry is watching a new generation of studios.</b><p>Studios compete for audiences, talent and release dates.</p></article><article class="newsItem"><span>MARKET</span><b>Global cinema enters a new week.</b><p>Watch trends before committing to your next project.</p></article></section><section class="dashCard milestones"><div class="cardHead"><div><small>CAREER</small><h2>Studio Milestones</h2></div></div><div class="milestone"><span class="done">✓</span><div><b>Found your studio</b><small>Welcome to the industry.</small></div></div><div class="milestone"><span>○</span><div><b>Release your first film</b><small>Bring your first story to audiences.</small></div></div><div class="milestone"><span>○</span><div><b>Reach $100M box office</b><small>Become a commercial force.</small></div></div></section></div><nav class="dashNav"><button data-section="MOVIES">🎬<span>MOVIES</span></button><button data-section="TALENT">👥<span>TALENT</span></button><button data-section="INDUSTRY">🏭<span>INDUSTRY</span></button><button data-section="FINANCE">📊<span>FINANCE</span></button><button data-section="NEWS">📰<span>NEWS</span></button><button data-section="STUDIO">🏢<span>STUDIO</span></button></nav><footer class="dashFooter"><div><small>WEEK ${s.week}</small><b>Ready to advance?</b></div><button id="next" class="nextWeek">NEXT WEEK <span>→</span></button></footer></main><div class="notice"></div>`;const state=structuredClone(s);document.querySelector('#save').onclick=()=>saveCurrent(state);document.querySelector('#back').onclick=render;document.querySelector('#next').onclick=()=>showWeeklyReport(state);document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>openSection(state,b.dataset.section));document.querySelector('#viewMovies').onclick=()=>openSection(state,'MOVIES');document.querySelector('#viewNews').onclick=()=>openSection(state,'NEWS');document.querySelector('.projectBtn').onclick=()=>createMovie(state);renderProjects(state)}
function renderProjects(state){const card=document.querySelector('.dashCard.projects');if(!card||!state.films?.length)return;const list=state.films.slice(0,4).map(f=>{const total=Math.max(1,+f.totalWeeks||4),done=Math.min(total,+f.stageWeek||1),pct=Math.round(done/total*100);return `<article class="projectRow"><div class="projectPoster">🎬</div><div class="projectInfo"><div class="projectTop"><b>${esc(f.title)}</b><span>${esc(f.genre)}</span></div><p>${filmName(f.stage)} · Week ${done}/${total}</p><div class="projectProgress"><i style="width:${pct}%"></i></div><small>${pct}% complete · $${Number(f.budget).toLocaleString()} budget</small></div><button class="projectOpen" data-film="${f.id}">OPEN</button></article>`}).join('');card.querySelector('.emptyProject').outerHTML=`<div class="projectList">${list}</div><button class="projectBtn secondary" id="anotherMovie">+ MAKE ANOTHER MOVIE</button>`;document.querySelector('#anotherMovie').onclick=()=>createMovie(state);document.querySelectorAll('.projectOpen').forEach(b=>b.onclick=()=>{const f=state.films.find(x=>String(x.id)===String(b.dataset.film));if(f)showFilmDetails(state,f)})}
function openSection(state,section,filmId=null){const e=document.createElement('div');e.className='modal dashSectionModal';const films=state.films||[];let body='';if(section==='MOVIES')body=`<div class="sectionHeroMetric"><b>${films.length}</b><span>Films in your library</span></div><div class="sectionList">${films.length?films.map(f=>`<button class="sectionRow" data-film="${f.id}"><span>🎬</span><div><b>${esc(f.title)}</b><small>${esc(f.genre)} · ${filmName(f.stage)} · Week ${f.stageWeek}/${f.totalWeeks}</small></div><strong>DETAILS →</strong></button>`).join(''):'<div class="sectionEmpty"><b>No films yet.</b><span>Create your first movie to begin your slate.</span></div>'}</div><button class="menuBtn primary" id="createSectionMovie">CREATE A MOVIE →</button>`;
if(section==='TALENT'){const target=filmId?films.find(f=>String(f.id)===String(filmId)):null;const missing=target?crewRoles.filter(r=>!target.crew?.[r[0]]):[];const categories=[['Actor','ACTORS'],['Director','DIRECTORS'],['Writer','WRITERS'],['Composer','COMPOSERS'],['Cinematographer','CINEMATOGRAPHERS'],['Editor','EDITORS'],['VFX Supervisor','VFX']];const activeCat='All';body=`${target?`<div class="crewNeed"><div><small>HIRING FOR</small><b>${esc(target.title)}</b><span>${missing.length?missing.length+' core roles still needed':'Core crew complete'}</span></div>${missing.length?`<div class="crewNeedList">${missing.map(r=>`<button class="crewNeedBtn" data-role="${r[0]}">${r[1]} · FIND IN TALENT →</button>`).join('')}</div>`:''}</div>`:''}<div class="deepGrid"><div class="deepCard"><small>WHAT'S HAPPENING</small><h3>Talent market is active</h3><p>Popularity affects fees and availability.</p></div><div class="deepCard"><small>YOUR NETWORK</small><h3>${Math.min(8,films.length*2)} relationships</h3><p>Your projects build connections over time.</p></div></div><div class="talentTabs"><button class="talentTab active" data-cat="All">ALL</button>${categories.map(c=>`<button class="talentTab" data-cat="${c[0]}">${c[1]}</button>`).join('')}</div><div class="sectionTitleRow"><b>AVAILABLE TALENT</b><span>${target?'Hire directly for this film':'Tap for details'}</span></div><div class="talentList" id="talentList">${talent.map((t,i)=>`<button class="talentRow" data-talent="${i}" data-talent-role="${esc(t[1])}"><span class="talentAvatar">${t[0][0]}</span><div><b>${t[0]}</b><small>${t[1]} · ⭐ ${t[2]} · ${t[3]}M asking</small></div><strong>VIEW →</strong></button>`).join('')}</div>`;}
if(section==='INDUSTRY'){const studios=window.INDUSTRY_STUDIOS||[];const streamers=window.INDUSTRY_STREAMERS||[];body=`<div class="deepGrid"><div class="deepCard"><small>MARKET HEALTH</small><h3>Strong · 82/100</h3><p>Studios are actively investing.</p></div><div class="deepCard"><small>TRENDING GENRE</small><h3>${['Drama','Sci-Fi','Horror','Animation','Thriller'][Math.floor(state.week/4)%5]}</h3><p>Audience interest shifts as the simulation advances.</p></div></div><div class="sectionTitleRow"><b>REAL INDUSTRY STUDIOS</b><span>${studios.length} reference companies</span></div><div class="rivalList">${studios.map(r=>`<div class="rivalRow"><div><b>${esc(r.name)}</b><small>${esc(r.type)} · Reputation ${r.reputation}/100</small></div><strong>ACTIVE</strong></div>`).join('')}</div><div class="sectionTitleRow"><b>REAL STREAMING PLATFORMS</b><span>Acquisition market</span></div><div class="rivalList">${streamers.map(r=>`<div class="rivalRow"><div><b>${esc(r.name)}</b><small>${esc(r.appetite)} acquisition appetite</small></div><strong>${esc(r.focus.slice(0,2).join(' · '))}</strong></div>`).join('')}</div><div class="deepCard"><small>WHY IT MATTERS</small><p>These are real-world reference companies and platforms; your save creates a fictional alternate timeline around them.</p></div>`;}
if(section==='FINANCE')body=`<div class="financeHero"><small>CURRENT CASH</small><b>$${Number(state.money).toLocaleString()}</b><span>Available studio funds</span></div><div class="financeRows"><div><span>Film investment</span><b>$${films.reduce((a,f)=>a+Number(f.budget||0),0).toLocaleString()}</b></div><div><span>Estimated weekly revenue</span><b>+$${Math.round(Number(state.money)*.018).toLocaleString()}</b></div><div><span>Estimated weekly expenses</span><b>−$${(650000+films.length*90000).toLocaleString()}</b></div><div><span>Estimated net change</span><b>Calculated after the week</b></div></div>`;
if(section==='NEWS')body=`<div class="newsFeed"><article><small>INDUSTRY · THIS WEEK</small><b>Studios are competing for the next major audience.</b><span>Release dates, talent and streaming deals remain competitive.</span></article><article><small>MARKET</small><b>Genre demand is changing.</b><span>Keep an eye on the Industry section before planning releases.</span></article>${films[0]?`<article><small>YOUR STUDIO</small><b>${esc(films[0].title)} is in ${filmName(films[0].stage)}.</b><span>Open the movie to see exactly what it needs next.</span></article>`:''}</div>`;
if(section==='STUDIO')body=`<div class="studioProfileCard"><div class="studioProfileLogo">${state.studio?.logo?.icon||'★'}</div><div><small>YOUR COMPANY</small><h3>${esc(state.studioName)}</h3><p>Year ${state.year} · Week ${state.week}</p></div></div><div class="deepGrid"><div class="deepCard"><small>REPUTATION</small><h3>${state.reputation}/100</h3><p>Industry standing.</p></div><div class="deepCard"><small>ENERGY</small><h3>${state.energy}/100</h3><p>Used by major studio actions.</p></div><div class="deepCard"><small>SPECIALTY</small><h3>${esc(state.studio?.specialty||'Blockbuster Entertainment')}</h3><p>Starting identity.</p></div><div class="deepCard"><small>CAREER</small><h3>${films.length} films</h3><p>${state.awards?.length||0} awards.</p></div></div>`;
const info={MOVIES:['🎬','Movies','Your slate and film pipeline.'],TALENT:['👥','Talent','Actors, directors and creative professionals.'],INDUSTRY:['🏭','Industry','The global film business around you.'],FINANCE:['📊','Finance','Your money, spending and performance.'],NEWS:['📰','News','What is happening across the film world.'],STUDIO:['🏢','Studio','The company behind your films.']}[section];e.innerHTML=`<div class="panel dashSectionPanel"><header class="sectionHero"><button class="close">×</button><div class="sectionIcon">${info[0]}</div><div><small>STUDIO MANAGEMENT · ${section}</small><h2>${info[1]}</h2><p>${info[2]}</p></div></header><div class="sectionBody">${body}</div><footer class="sectionFooter"><button class="menuBtn" id="sectionClose">BACK TO DASHBOARD</button></footer></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();e.querySelector('#sectionClose').onclick=()=>e.remove();const cm=e.querySelector('#createSectionMovie');if(cm)cm.onclick=()=>{e.remove();createMovie(state)};e.querySelectorAll('[data-film]').forEach(b=>b.onclick=()=>{const f=films.find(x=>String(x.id)===String(b.dataset.film));if(f){e.remove();showFilmDetails(state,f)}});e.querySelectorAll('[data-talent]').forEach(b=>b.onclick=()=>showTalent(state,talent[+b.dataset.talent],filmId));e.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{e.querySelectorAll('[data-cat]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const cat=b.dataset.cat;e.querySelectorAll('[data-talent]').forEach(row=>{row.style.display=cat==='All'||row.dataset.talentRole===cat?'grid':'none'})});e.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{const role=b.dataset.role;const cat=role==='director'?'Director':role==='writer'?'Writer':role==='composer'?'Composer':role==='cinematographer'?'Cinematographer':role==='vfx'?'VFX Supervisor':'Editor';e.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x.dataset.cat===cat));e.querySelectorAll('[data-talent]').forEach(row=>{row.style.display=row.dataset.talentRole===cat?'grid':'none'});});}
function showTalent(state,t,filmId){const e=document.createElement('div');e.className='modal talentDetailModal';const target=filmId?state.films.find(f=>String(f.id)===String(filmId)):null;const roleKey=({'Director':'director','Writer':'writer','Cinematographer':'cinematographer','Composer':'composer','VFX Supervisor':'vfx','Editor':'editor','Actor':'leadActor'})[t[1]];e.innerHTML=`<div class="panel talentDetailPanel"><button class="close">×</button><div class="talentDetailHead"><span>${t[0][0]}</span><div><small>${t[1]}</small><h2>${t[0]}</h2><p>⭐ Talent ${t[2]} · Popularity ${Math.max(1,t[2]-3)}/100</p></div></div><div class="deepGrid"><div class="deepCard"><small>ASKING FEE</small><h3>$${t[3]}M</h3><p>Current market estimate.</p></div><div class="deepCard"><small>RELIABILITY</small><h3>${Math.max(1,t[2]-3)}/100</h3><p>Higher reliability means less scheduling risk.</p></div><div class="deepCard"><small>FIT</small><h3>${Math.min(99,t[2]+(target&&target.genre==='Drama'&&t[1]==='Writer'?4:0))}%</h3><p>Estimated compatibility with this project.</p></div></div><button class="menuBtn primary" id="offerTalent">${target?'HIRE FOR THIS FILM':'MAKE AN OFFER'}</button></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();e.querySelector('#offerTalent').onclick=()=>{if(target&&roleKey){target.crew=target.crew||{};if(target.crew[roleKey])return toast('That role is already filled.');state.talentContracts=state.talentContracts||{};const existing=state.talentContracts[t[0]];if(existing&&existing.filmId!==target.id)return toast(`${t[0]} is already committed to ${existing.title}.`);const cost=t[3]*1000000;if(state.money<cost)return toast('Not enough cash for this talent.');state.money-=cost;state.transactions=state.transactions||[];state.transactions.push({week:state.week,year:state.year,type:'talent',amount:-cost,description:`${t[0]} hired for ${target.title}`});state.talentContracts[t[0]]={filmId:target.id,title:target.title,role:t[1],fee:cost,startWeek:state.week};state.relationships=state.relationships||{};state.relationships[t[0]]={score:Math.min(100,(state.relationships[t[0]]?.score||40)+8),lastProject:target.title};target.crew[roleKey]=t[0];target.history=target.history||[];target.history.push({week:state.week,year:state.year,event:`${t[0]} hired`,detail:`${t[1]} attached for $${cost.toLocaleString()}.`});target.quality=Math.min(99,target.quality+Math.round(t[2]/30));if(roleKey==='writer')target.story=Math.min(99,(target.story||50)+Math.round(t[2]/12));if(roleKey==='director')target.direction=Math.min(99,(target.direction||50)+Math.round(t[2]/12));if(roleKey==='cinematographer')target.visuals=Math.min(99,(target.visuals||50)+Math.round(t[2]/12));saveCurrent(state,true);e.remove();toast(`${t[0]} hired as ${t[1]} for ${target.title}.`);showFilmDetails(state,target)}else{e.remove();toast(`Offer prepared for ${t[0]}.`)}}}
function releaseFilm(state,film){const e=document.createElement('div');e.className='modal releaseModal';let strategy='Wide Release',territories='Global',marketing=0,releaseWeek=state.week+1;const options=[['Limited Release','$5M',5000000],['Wide Release','$15M',15000000],['Major Campaign','$30M',30000000],['Global Event','$50M',50000000]];const maxWeek=state.week+12;e.innerHTML=`<div class="panel releasePanel"><header class="releaseHero"><button class="close">×</button><small>RELEASE DEPARTMENT · FINAL DECISION</small><h2>${esc(film.title)}</h2><p>${esc(film.genre)} · Quality ${film.quality||50}/99 · Audience Appeal ${film.audience||50}/99</p></header><div class="releaseBody"><section class="releaseBlock"><div class="releaseTitle">RELEASE STRATEGY</div><div class="releaseChoices">${options.map(x=>`<button class="releaseChoice ${x[0]===strategy?'chosen':''}" data-strategy="${x[0]}" data-cost="${x[2]}"><b>${x[0]}</b><span>${x[1]} marketing</span><small>${x[0]==='Limited Release'?'Build prestige slowly':x[0]==='Wide Release'?'Balanced theatrical launch':x[0]==='Major Campaign'?'High awareness campaign':'Maximum opening-week push'}</small></button>`).join('')}</div></section><section class="releaseBlock"><div class="releaseTitle">RELEASE WINDOW</div><div class="releaseSummary"><div><small>YOUR RELEASE</small><b>Week ${releaseWeek}</b></div><div><small>MARKET</small><b>${territories}</b></div><div><small>COMPETITION</small><b id="releaseCompetition">Checking...</b></div></div><div class="releaseWeeks">${Array.from({length:6},(_,i)=>{const w=state.week+i+1;return `<button class="weekChoice ${w===releaseWeek?'chosen':''}" data-week="${w}">W${w}</button>`}).join('')}</div></section><section class="releaseBlock"><div class="releaseTitle">WHY THIS MATTERS</div><p class="releaseExplain">Your release strategy affects opening-week demand, marketing cost, competition exposure, and the film's chance of attracting streaming and awards attention.</p><div class="releasePreview"><span>Estimated launch strength</span><b id="releaseScore">${Math.min(99,Math.round((film.quality+film.audience)/2))}/100</b></div></section></div><footer class="releaseFooter"><div><small>TOTAL MARKETING</small><b id="releaseCost">$${marketing.toLocaleString()}</b></div><button class="menuBtn primary" id="confirmRelease">SCHEDULE RELEASE →</button></footer></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();const refresh=()=>{const chosen=e.querySelector('.releaseChoice.chosen');marketing=Number(chosen?.dataset.cost||0);const score=Math.min(99,Math.round(((film.quality||50)+(film.audience||50))/2)+(strategy==='Global Event'?7:strategy==='Major Campaign'?4:strategy==='Wide Release'?2:-2));e.querySelector('#releaseCost').textContent=`$${marketing.toLocaleString()}`;e.querySelector('#releaseScore').textContent=`${score}/100`;e.querySelector('#releaseCompetition').textContent=state.industry?.marketHealth<70?'Low':'Moderate'};e.querySelectorAll('[data-strategy]').forEach(b=>b.onclick=()=>{strategy=b.dataset.strategy;e.querySelectorAll('[data-strategy]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');refresh()});e.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{releaseWeek=+b.dataset.week;e.querySelectorAll('[data-week]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');refresh()});refresh();e.querySelector('#confirmRelease').onclick=()=>{if(state.money<marketing)return toast('Not enough cash for this release campaign.');film.stage='released';film.releasedWeek=releaseWeek;film.releaseDate=`Year ${state.year}, Week ${releaseWeek}`;film.marketingBudget=marketing;film.spent=(film.spent||0)+marketing;film.boxOffice=0;film.revenue=0;film.streamingOffer=null;film.releaseStrategy=strategy;film.history=film.history||[];film.history.push({week:state.week,year:state.year,event:'Release scheduled',detail:`${strategy} · ${territories} · Week ${releaseWeek} · $${marketing.toLocaleString()} marketing.`});state.money-=marketing;state.transactions=state.transactions||[];state.transactions.push({week:state.week,year:state.year,type:'marketing',amount:-marketing,description:`${film.title} release campaign`});state.news=state.news||[];state.news.unshift({week:state.week,year:state.year,type:'release',title:`${film.title} gets a release date`,body:`${film.title} is scheduled for a ${strategy.toLowerCase()} in Week ${releaseWeek}.`});state.reputation=Math.min(100,state.reputation+(film.quality>=80?2:0));saveCurrent(state,true);e.remove();start(state);toast(`${film.title} is scheduled for Week ${releaseWeek}.`)}}function showFilmDetails(state,film){const e=document.createElement('div');e.className='modal filmDetailsModal';const total=Math.max(1,+film.totalWeeks||4),done=Math.min(total,+film.stageWeek||1),pct=Math.round(done/total*100);const missing=crewRoles.filter(r=>!film.crew?.[r[0]]);e.innerHTML=`<div class="panel filmDetailsPanel"><div class="filmDetailsHero"><button class="close">×</button><div class="eyebrow">FEATURE FILM · PROJECT FILE</div><h2>${esc(film.title)}</h2><p>${esc(film.genre)} · $${Number(film.budget).toLocaleString()} budget · Week ${done}/${total}</p><div class="filmHeroProgress"><i style="width:${pct}%"></i></div><b>${filmName(film.stage)} · ${pct}% complete</b></div><div class="filmDetailsBody"><section class="filmSection"><div class="filmSectionTitle">WHAT HAPPENS NEXT</div><div class="nextDecision"><b>${missing.length?`Need ${missing.length} core crew member${missing.length>1?'s':''}`:filmName(film.stage)}</b><span>${missing.length?'Hire them from the Talent section before the movie can progress.':'Your current stage is progressing with the core crew attached.'}</span></div>${missing.length?`<button class="menuBtn primary" id="hireCrew">👥 HIRE CREW IN TALENT</button>`:''}</section><section class="filmSection"><div class="filmSectionTitle">PRODUCTION TIMELINE</div><div class="filmTimeline">${filmStages.slice(0,6).map((x,i)=>{const cur=filmStages.findIndex(s=>s[0]===film.stage);return `<div class="filmTimelineRow ${i<cur?'done':i===cur?'current':''}"><span>${i<cur?'✓':i===cur?'●':'○'}</span><b>${x[1]}</b><small>${i<cur?'Completed':i===cur?'In progress':'Not started'}</small></div>`}).join('')}</div></section><section class="filmSection"><div class="filmSectionTitle">FILM PROFILE</div><div class="filmMetrics"><div><small>STORY</small><b>${film.story||50}</b></div><div><small>DIRECTION</small><b>${film.direction||50}</b></div><div><small>ACTING</small><b>${film.acting||50}</b></div><div><small>VISUALS</small><b>${film.visuals||50}</b></div><div><small>AUDIENCE APPEAL</small><b>${film.audience||50}</b></div><div><small>CURRENT QUALITY</small><b>${film.quality||50}</b></div></div></section><section class="filmSection"><div class="filmSectionTitle">FINANCIALS</div><div class="filmFinance"><span>Production Budget</span><b>$${Number(film.budget||0).toLocaleString()}</b><span>Spent So Far</span><b>$${Number(film.spent||0).toLocaleString()}</b><span>Marketing Budget</span><b>${film.marketingBudget?'$'+Number(film.marketingBudget).toLocaleString():'Not assigned'}</b></div></section><section class="filmSection"><div class="filmSectionTitle">CAST & CREW</div><div class="filmCrew">${crewRoles.map(r=>`<div>${r[1]} <b>${film.crew?.[r[0]]||'Not hired'}</b></div>`).join('')}<div>Lead Actor <b>${film.crew?.leadActor||'Not cast'}</b></div><div>Lead Actress <b>${film.crew?.leadActress||'Not cast'}</b></div></div></section><section class="filmSection filmHistory"><div class="filmSectionTitle">FILM HISTORY</div><div class="historyRow"><span>Week ${film.createdWeek||state.week}</span><b>Concept created</b></div><div class="historyRow"><span>Week ${done}</span><b>${filmName(film.stage)} in progress</b></div></section></div><div class="filmDetailsFooter"><button class="menuBtn" id="closeFilm">CLOSE</button><button class="menuBtn primary" id="filmAction">${film.stage==='ready'?'RELEASE FILM':'VIEW CURRENT STAGE'}</button></div></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();e.querySelector('#closeFilm').onclick=()=>e.remove();const hc=e.querySelector('#hireCrew');if(hc)hc.onclick=()=>{e.remove();openSection(state,'TALENT',film.id)};e.querySelector('#filmAction').onclick=()=>{if(film.stage==='ready'){e.remove();releaseFilm(state,film)}else toast(`${filmName(film.stage)} is handled from the movie project.`)}}
function advanceFilms(state){(state.films||[]).forEach(f=>{if(f.stage==='released')return;const missing=crewRoles.filter(r=>!f.crew?.[r[0]]);if(missing.length&&['preproduction','production','postproduction'].includes(f.stage)){f.history=f.history||[];f.history.push({week:state.week,year:state.year,event:'Production paused',detail:`Waiting for ${missing.map(x=>x[1]).join(', ')}.`});return;}const stepCost=Math.round((+f.budget||30000000)/Math.max(4,+f.totalWeeks||4));f.stageWeek=(+f.stageWeek||1)+1;f.spent=Math.min(+f.budget||0,(+f.spent||0)+stepCost);f.quality=Math.min(99,Math.round((f.story+f.direction+f.acting+f.visuals+f.music+f.vfx)/6));f.audience=Math.min(99,Math.round((f.quality*0.72)+(state.industry?.boxOfficeIndex||100)/10));f.history=f.history||[];f.history.push({week:state.week,year:state.year,event:`${filmName(f.stage)} progressed`,detail:`Quality ${f.quality}/99 · Spent $${stepCost.toLocaleString()}.`});if(f.stageWeek>(+f.totalWeeks||4)){const idx=filmStages.findIndex(x=>x[0]===f.stage);if(idx<5){f.stage=filmStages[idx+1][0];f.stageWeek=1;f.totalWeeks=f.stage==='production'?Math.max(8,Math.ceil((f.budget||30000000)/8000000)):f.stage==='postproduction'?Math.max(4,Math.ceil((f.budget||30000000)/12000000)):f.stage==='marketing'?8:4;f.history.push({week:state.week,year:state.year,event:`Entered ${filmName(f.stage)}`,detail:'The next production stage is now active.'});}}});}
const events=[['Industry Buzz','A trade publication highlighted several studios to watch this year.','industry'],['Talent Rumors','A sought-after creative professional is attracting offers from several studios.','talent'],['Streaming Competition','Streaming platforms are competing more aggressively for quality films.','industry'],['Release Window Opens','A rival delayed a major film, creating a possible opening in the release calendar.','industry'],['Festival Season','Festival programmers are beginning to discuss this year’s strongest films.','industry'],['Marketing Trend','Influencer campaigns are becoming more important for film launches.','industry'],['Rival Investment','A competitor announced a major production budget.','industry'],['New Production Announced','A rival studio has officially greenlit a major new film, adding another title to the competition calendar.','industry'],['Talent Race','Several studios are competing for the same high-profile creative talent.','talent'],['Production Costs Rise','Equipment and production services are becoming more expensive this quarter.','industry'],['Unexpected Breakout','A previously unknown performer is suddenly attracting major industry attention.','talent'],['Streaming Deal Rush','Major platforms are increasing acquisitions after a strong run of theatrical releases.','industry'],['Your Film Gets Attention','Your project is starting to generate industry chatter among early observers.','film'],['Script Praise','Your film’s concept and script are receiving encouraging early reactions.','film'],['Production Delay','A production issue has added pressure to your current schedule.','film'],['Crew Chemistry','Your assembled crew is working particularly well together this week.','crew'],['Test Screening Surprise','An early audience response to your film is stronger than expected.','film'],['Streaming Interest','A streaming platform has begun watching your film closely after its strong performance.','released'],['Nothing Happened This Week','The studio continued normal operations. No major events affected your company.','quiet']];
function showWeeklyReport(state){const prev=state.week;advanceFilms(state);const eventCount=Math.random()<.18?3:(Math.random()<.48?2:1);const contextual=events.filter(x=>{const tag=x[2];if(tag==='film')return (state.films||[]).length>0;if(tag==='released')return (state.films||[]).some(f=>f.stage==='released');if(tag==='crew')return (state.films||[]).some(f=>Object.keys(f.crew||{}).length>0);return true});const pool=contextual.length?contextual:events;const chosen=Math.random()<.14?[]:Array.from({length:eventCount},()=>pool[Math.floor(Math.random()*pool.length)]).filter((x,i,a)=>a.findIndex(y=>y[0]===x[0])===i);if(chosen.length){state.news=state.news||[];chosen.forEach(x=>{state.news.unshift({week:prev,year:state.year,title:x[0],body:x[1],type:x[2]});if(x[0]==='Production Costs Rise')state.industry.marketHealth=Math.max(40,state.industry.marketHealth-3);if(x[0]==='Rival Investment')state.reputation=Math.max(1,state.reputation-1);if(x[0]==='Crew Chemistry')(state.films||[]).filter(f=>f.stage!=='released').forEach(f=>{f.quality=Math.min(99,(f.quality||50)+3);f.history=f.history||[];f.history.push({week:prev,year:state.year,event:'Crew chemistry bonus',detail:'The team worked unusually well together.'});});if(x[0]==='Production Delay')(state.films||[]).filter(f=>f.stage!=='released').slice(0,1).forEach(f=>{f.stageWeek=Math.max(1,(f.stageWeek||1)-1);f.spent=Math.min(f.budget,(f.spent||0)+Math.round(f.budget*.015));f.history=f.history||[];f.history.push({week:prev,year:state.year,event:'Unexpected production delay',detail:'Schedule slipped and costs increased.'});});if(x[0]==='Your Film Gets Attention')(state.films||[]).filter(f=>f.stage!=='released').forEach(f=>f.audience=Math.min(99,(f.audience||50)+4));if(x[0]==='Test Screening Surprise')(state.films||[]).filter(f=>f.stage==='postproduction').forEach(f=>{f.quality=Math.min(99,(f.quality||50)+5);f.audience=Math.min(99,(f.audience||50)+6);});if(x[0]==='Streaming Interest')released.forEach(f=>{const offer=Math.round((f.boxOffice||0)*.18);f.streamingOffer=offer;f.history=f.history||[];f.history.push({week:prev,year:state.year,event:'Streaming interest',detail:`A platform is considering an offer around $${offer.toLocaleString()}.`});});});state.news=state.news.slice(0,60);}const released=(state.films||[]).filter(f=>f.stage==='released');released.forEach(f=>{const weekly=Math.round((Number(f.budget||0)*0.012)*(f.audience/70)*((state.industry?.boxOfficeIndex||100)/100));f.boxOffice=(f.boxOffice||0)+weekly;f.revenue=(f.revenue||0)+weekly;});const revenue=Math.round(released.reduce((a,f)=>a+Math.max(0,Number(f.boxOffice||0)-Number(f.revenue||0)+Number(f.revenue||0)),0));const expenses=Math.round(650000+(state.films||[]).reduce((a,f)=>a+(f.stage==='released'?0:Math.round(Number(f.budget||0)/Math.max(4,Number(f.totalWeeks||4)))),0));const net=revenue-expenses;state.transactions=state.transactions||[];if(revenue)state.transactions.push({week:prev,year:state.year,type:'boxoffice',amount:revenue,description:'Weekly box office revenue'});if(expenses)state.transactions.push({week:prev,year:state.year,type:'production',amount:-expenses,description:'Weekly studio and production expenses'});state.industry=state.industry||{trend:'Drama',marketHealth:82,boxOfficeIndex:100,streamingDemand:78};state.industry.trend=['Drama','Sci-Fi','Horror','Animation','Thriller','Action'][Math.floor(prev/5)%6];state.industry.marketHealth=Math.max(55,Math.min(98,state.industry.marketHealth+(Math.random()<.5?-1:1)*2));state.industry.boxOfficeIndex=Math.max(80,Math.min(125,state.industry.boxOfficeIndex+(Math.random()<.5?-2:2)));const e=document.createElement('div');e.className='modal weeklyModal';e.innerHTML=`<div class="panel weeklyPanel"><div class="weeklyHero"><small>WEEK ${String(prev).padStart(2,'0')} · STUDIO REPORT</small><h2>Weekly Analysis</h2><p>${esc(state.studioName)} · The week has been processed.</p></div><div class="weeklyBody"><section class="reportBlock"><div class="reportTitle">💰 FINANCIAL PERFORMANCE</div><div class="reportGrid"><div><small>STARTING CASH</small><b>$${Number(state.money).toLocaleString()}</b></div><div><small>REVENUE</small><b class="positive">+$${revenue.toLocaleString()}</b></div><div><small>EXPENSES</small><b class="negative">−$${expenses.toLocaleString()}</b></div><div><small>NET CHANGE</small><b class="${net>=0?'positive':'negative'}">${net>=0?'+':''}$${net.toLocaleString()}</b></div></div></section><section class="reportBlock"><div class="reportTitle">🎬 PROJECT ACTIVITY</div><div class="activityRows"><div><span>Films in production</span><b>${state.films?.length||0}</b></div><div><span>Projects advanced</span><b>${state.films?.length||0}</b></div><div><span>Energy</span><b>${state.energy}/100</b></div></div></section>${chosen.length?chosen.map(x=>`<section class="reportHighlight"><small>WEEKLY EVENT</small><h3>${x[0]}</h3><p>${x[1]}</p></section>`).join(''):'<section class="reportHighlight"><small>QUIET WEEK</small><h3>Nothing Happened This Week</h3><p>Your studio continued normal operations. Sometimes a quiet week is a good week.</p></section>'}</div><div class="weeklyFooter"><div><small>NEXT</small><b>Week ${prev>=52?1:prev+1} · ${prev>=52?state.year+1:state.year}</b></div><button class="menuBtn primary" id="continueWeek">CONTINUE →</button></div></div>`;document.body.appendChild(e);e.querySelector('#continueWeek').onclick=()=>{state.week=prev>=52?1:prev+1;if(prev>=52)state.year++;state.energy=100;state.money=Math.max(0,state.money+net);saveCurrent(state,true);e.remove();start(state);toast(`Week ${state.week} begins.`)}}
function loadModal(){const ss=slots(),e=document.createElement('div');e.className='modal';e.innerHTML=`<div class="panel"><div class="panelHead"><button class="close">×</button><h2>Load Studio</h2><p>Choose a saved career.</p></div><div class="slots">${Array.from({length:5},(_,i)=>{const s=ss[i];return s?`<div class="slot"><div><h3>${esc(s.studioName)}</h3><p>Year ${s.year} · Week ${s.week} · $${Number(s.money).toLocaleString()}</p></div><div class="slotActions"><button class="mini gold" data-load="${i}">LOAD</button><button class="mini" data-del="${i}">DELETE</button></div></div>`:`<div class="slot empty"><div><h3>Slot ${i+1}</h3><p>Empty</p></div></div>`}).join('')}</div></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();e.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{const s=slots()[+b.dataset.load];e.remove();start(s)});e.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{const i=+b.dataset.del;if(confirm('Delete this studio save?')){const x=slots();x[i]=null;write(x);e.remove();loadModal()}})}
render();
})();